STATEMENTS = (
    "CREATE TABLE expense_categories(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,treatment TEXT NOT NULL CHECK(treatment IN('inventory','allocated','capital','operating')),archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)))",
    "INSERT INTO expense_categories(name,treatment) VALUES('Filamentos','inventory'),('Materiais auxiliares','inventory'),('Energia','allocated'),('Manutenção','allocated'),('Equipamentos','capital'),('Embalagens','inventory'),('Fretes','operating'),('Taxas de pagamento','operating'),('Outras despesas','operating')",
    "CREATE TABLE payables(id INTEGER PRIMARY KEY AUTOINCREMENT,description TEXT NOT NULL,category_id INTEGER NOT NULL REFERENCES expense_categories(id),category_snapshot TEXT NOT NULL,supplier TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(amount_cents>0),incurred_on TEXT NOT NULL,created_at TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('active','cancelled')),reason TEXT NOT NULL DEFAULT '',operation_key TEXT NOT NULL UNIQUE)",
    "CREATE TABLE payable_installments(id INTEGER PRIMARY KEY AUTOINCREMENT,payable_id INTEGER NOT NULL REFERENCES payables(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),due_on TEXT)",
    "CREATE TABLE payable_payments(id INTEGER PRIMARY KEY AUTOINCREMENT,installment_id INTEGER NOT NULL REFERENCES payable_installments(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),fee_cents INTEGER NOT NULL CHECK(fee_cents>=0),paid_on TEXT NOT NULL,method TEXT NOT NULL,created_at TEXT NOT NULL,operation_key TEXT NOT NULL UNIQUE)",
    "CREATE TABLE finance_entries(id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL CHECK(kind IN('capital_in','capital_out','opening_in','opening_out')),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),occurred_on TEXT NOT NULL,description TEXT NOT NULL,responsible TEXT NOT NULL,created_at TEXT NOT NULL,reversal_of INTEGER UNIQUE REFERENCES finance_entries(id),operation_key TEXT NOT NULL UNIQUE)",
    "CREATE TABLE finance_proofs(id INTEGER PRIMARY KEY AUTOINCREMENT,payment_id INTEGER UNIQUE REFERENCES payable_payments(id),entry_id INTEGER UNIQUE REFERENCES finance_entries(id),path TEXT NOT NULL UNIQUE,sha256 TEXT NOT NULL,original_name TEXT NOT NULL,created_at TEXT NOT NULL,CHECK((payment_id IS NOT NULL)+(entry_id IS NOT NULL)=1))",
    "CREATE TABLE financial_costs(id INTEGER PRIMARY KEY AUTOINCREMENT,movement_id INTEGER NOT NULL UNIQUE REFERENCES stock_movements(id),item_id INTEGER NOT NULL REFERENCES order_items(id),piece_id INTEGER NOT NULL REFERENCES pieces(id),printer_id INTEGER REFERENCES printers(id),product_id INTEGER REFERENCES products(id),cost_cents INTEGER NOT NULL CHECK(cost_cents>=0),occurred_on TEXT NOT NULL,snapshot TEXT NOT NULL)",
    "CREATE TABLE financial_returns(return_id INTEGER PRIMARY KEY REFERENCES order_returns(id),cost_id INTEGER NOT NULL REFERENCES financial_costs(id),cost_cents INTEGER NOT NULL CHECK(cost_cents>=0),occurred_on TEXT NOT NULL)",
    "CREATE TABLE finance_purchases(id INTEGER PRIMARY KEY AUTOINCREMENT,payable_id INTEGER NOT NULL UNIQUE REFERENCES payables(id),filament_id INTEGER UNIQUE REFERENCES filaments(id),material_id INTEGER REFERENCES materials(id),quantity_milli INTEGER NOT NULL CHECK(quantity_milli>0),operation_key TEXT NOT NULL UNIQUE,CHECK((filament_id IS NOT NULL)+(material_id IS NOT NULL)=1))",
)
